#include "../services/msgsync/spam_history.hpp"
#include "biglybtc/bencode.hpp"
#include <fstream>
#include <iostream>
#include <iterator>
#include <stdexcept>
#include <array>
using namespace biglybtc;namespace msg=services::msgsync;
namespace {void check(bool value,const char* reason){if(!value){throw std::runtime_error(reason);}}std::string text(const core::Node& node,std::string_view key){const auto* value=node.find(key);check(value&&value->type==core::Node::Type::Bytes,"Generated byte field");return std::string(value->bytes);}std::int64_t number(const core::Node& node,std::string_view key){const auto* value=node.find(key);check(value&&value->type==core::Node::Type::Integer,"Generated integer field");return value->integer;}}
int main(int argc,char** argv){try{
 check(argc==2,"Supply generated actual-original fixture");std::ifstream input(argv[1],std::ios::binary);check(bool(input),"Open original fixture");std::string bytes(std::istreambuf_iterator<char>(input),{});auto fixture=core::Document::parse(std::move(bytes),{8U*1024U*1024U,1024U*1024U,500000,32});check(bool(fixture),"Parse bounded original fixture");const auto* cases=fixture->find("cases");check(cases&&cases->type==core::Node::Type::List,"Original cases");std::size_t decisions=0;
 for(const auto& value:cases->children){msg::SpamHistory policy;check(value.type==core::Node::Type::List,"Operation list");for(const auto& op:value.children){const auto key=text(op,"pk"),history=text(op,"h");if(number(op,"op")==1){check(bool(policy.mark(key,!history.empty()&&history[0]!=0)),"Apply generated original spam toggle");}else{auto result=policy.accept(key,history);check(result&&*result==(number(op,"out")!=0),"Actual original spam history decision differs");++decisions;}check(policy.retained(key)<=16,"Original16-history window retained");}}
 msg::SpamHistory policy;check(!policy.mark({},true),"Empty identity refused");const std::array invalid{std::string(81,'x')};check(!policy.mark("Generated",true,invalid)&&!policy.marked("Generated"),"Invalid seed is refused before mutation");const std::array seed{std::string("AAAABBBB"),std::string("AAAACCCC")};check(bool(policy.mark("Generated",true,seed)),"Existing verified ledger histories seed the filter");auto a=policy.accept("Other","AAAA"),b=policy.accept("Other","BBBB");check(a&&!*a&&b&&*b,"Repeated shared relay is selected rather than a direct public-key ban");check(!policy.accept("Generated",std::string(81,'x'))&&policy.retained("Generated")==2,"Oversized history does not mutate state");check(bool(policy.mark("Generated",false)),"Clear explicit spam mark");a=policy.accept("Other","AAAA");check(a&&*a,"Removing last marked key clears derived filter");policy.clear();
 std::cout<<"PASS actual original spam history: "<<cases->children.size()<<" cases; "<<decisions<<" decisions; seed/window/limit/clear controls\n";return 0;
 }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}}
